2	name: ktor-patterns
3	description: Ktor client patterns for Android networking with content negotiation, error handling, and interceptors.
4	---
5	
6	# Ktor Client Patterns
7	
8	Modern HTTP client for Kotlin.
9	
10	## Client Setup
11	
12	```kotlin
13	val httpClient = HttpClient(OkHttp) {
14	    // JSON serialization
15	    install(ContentNegotiation) {
16	        json(Json {
17	            ignoreUnknownKeys = true
18	            isLenient = true
19	            prettyPrint = false
20	        })
21	    }
22	    
23	    // Timeouts
24	    install(HttpTimeout) {
25	        requestTimeoutMillis = 30_000
26	        connectTimeoutMillis = 10_000
27	        socketTimeoutMillis = 30_000
28	    }
29	    
30	    // Logging (debug only)
31	    install(Logging) {
32	        logger = Logger.ANDROID
33	        level = if (BuildConfig.DEBUG) LogLevel.BODY else LogLevel.NONE
34	    }
35	    
36	    // Default request config
37	    defaultRequest {
38	        url("https://api.example.com")
39	        contentType(ContentType.Application.Json)
40	    }
41	    
42	    // Auth
43	    install(Auth) {
44	        bearer {
45	            loadTokens {
46	                BearerTokens(tokenStorage.accessToken, tokenStorage.refreshToken)
47	            }
48	            refreshTokens {
49	                val response = client.post("auth/refresh") {
50	                    setBody(RefreshRequest(tokenStorage.refreshToken))
51	                }
52	                tokenStorage.save(response.body())
53	                BearerTokens(response.body<TokenResponse>().accessToken, response.body<TokenResponse>().refreshToken)
54	            }
55	        }
56	    }
57	}
58	```
59	
60	## API Definition
61	
62	```kotlin
63	class UserApi(private val client: HttpClient) {
64	    
65	    suspend fun getUsers(): List<UserDto> {
66	        return client.get("users").body()
67	    }
68	    
69	    suspend fun getUser(id: String): UserDto {
70	        return client.get("users/$id").body()
71	    }
72	    
73	    suspend fun createUser(request: CreateUserRequest): UserDto {
74	        return client.post("users") {
75	            setBody(request)
76	        }.body()
77	    }
78	    
79	    suspend fun updateUser(id: String, request: UpdateUserRequest): UserDto {
80	        return client.put("users/$id") {
81	            setBody(request)
82	        }.body()
83	    }
84	    
85	    suspend fun deleteUser(id: String) {
86	        client.delete("users/$id")
87	    }
88	}
89	```
90	
91	## Error Handling
92	
93	```kotlin
94	class ApiException(
95	    val statusCode: Int,
96	    override val message: String
97	) : Exception(message)
98	
99	suspend inline fun <reified T> HttpClient.safeRequest(
100	    block: HttpRequestBuilder.() -> Unit
101	): Result<T> = runCatching {
102	    val response = request(block)
103	    
104	    if (response.status.isSuccess()) {
105	        response.body<T>()
106	    } else {
107	        throw ApiException(
108	            statusCode = response.status.value,
109	            message = response.bodyAsText()
110	        )
111	    }
112	}
113	
114	// Usage
115	class UserRepository(private val api: UserApi, private val client: HttpClient) {
116	    suspend fun getUser(id: String): Result<User> {
117	        return client.safeRequest<UserDto> {
118	            url("users/$id")
119	            method = HttpMethod.Get
120	        }.map { it.toDomain() }
121	    }
122	}
123	```
124	
125	## DTOs and Mapping
126	
127	```kotlin
128	@Serializable
129	data class UserDto(
130	    val id: String,
131	    val email: String,
132	    @SerialName("first_name")
133	    val firstName: String,
134	    @SerialName("created_at")
135	    val createdAt: String
136	)
137	
138	fun UserDto.toDomain(): User = User(
139	    id = id,
140	    email = email,
141	    name = firstName,
142	    createdAt = Instant.parse(createdAt)
143	)
144	```
145	
146	## Interceptors
147	
148	```kotlin
149	val client = HttpClient(OkHttp) {
150	    // Request interceptor
151	    install(HttpSend) {
152	        intercept { request ->
153	            request.headers.append("X-Client-Version", BuildConfig.VERSION_NAME)
154	            execute(request)
155	        }
156	    }
157	}
158	```
159	
160	## Certificate Pinning
161	
162	```kotlin
163	val client = HttpClient(OkHttp) {
164	    engine {
165	        config {
166	            certificatePinner(
167	                CertificatePinner.Builder()
168	                    .add("api.example.com", "sha256/AAAA...")
169	                    .add("api.example.com", "sha256/BBBB...")  // Backup pin
170	                    .build()
171	            )
172	        }
173	    }
174	}
175	```
176	
177	---
178	
179	**Remember**: Ktor is coroutine-first. Embrace suspend functions, handle errors properly.
