251	
252	```kotlin
253	// commonMain/kotlin/network/NetworkExceptions.kt
254	sealed class NetworkException(message: String? = null) : Exception(message)
255	
256	class UnauthorizedException : NetworkException("User not authenticated")
257	class ForbiddenException : NetworkException("Access forbidden")
258	class NotFoundException : NetworkException("Resource not found")
259	class ServerException : NetworkException("Server error occurred")
260	class NetworkUnavailableException : NetworkException("Network unavailable")
261	class TimeoutException : NetworkException("Request timeout")
262	
263	// Wrap Ktor exceptions
264	fun Throwable.toNetworkException(): NetworkException {
265	    return when (this) {
266	        is NetworkException -> this
267	        is ClientRequestException -> when (response.status.value) {
268	            401 -> UnauthorizedException()
269	            403 -> ForbiddenException()
270	            404 -> NotFoundException()
271	            else -> NetworkException(message)
272	        }
273	        is ServerResponseException -> ServerException()
274	        is HttpRequestTimeoutException -> TimeoutException()
275	        is UnreachableAddressException,
276	        is ConnectTimeoutException -> NetworkUnavailableException()
277	        else -> NetworkException(message ?: "Unknown network error")
278	    }
279	}
