282	## Result Wrapper
283	
284	```kotlin
285	// commonMain/kotlin/network/ApiResult.kt
286	sealed class ApiResult<out T> {
287	    data class Success<T>(val data: T) : ApiResult<T>()
288	    data class Error(val error: NetworkException) : ApiResult<Nothing>()
289	
290	    suspend fun <R> map(transform: (T) -> R): ApiResult<R> = when (this) {
291	        is Success -> Success(transform(data))
292	        is Error -> this
293	    }
294	
295	    suspend fun <R> flatMap(transform: (T) -> ApiResult<R>): ApiResult<R> = when (this) {
296	        is Success -> transform(data)
297	        is Error -> this
298	    }
299	
300	    fun getOrNull(): T? = when (this) {
301	        is Success -> data
302	        is Error -> null
303	    }
304	
305	    fun getOrElse(defaultValue: T): T = when (this) {
306	        is Success -> data
307	        is Error -> defaultValue
308	    }
309	}
310	
311	suspend fun <T> apiCall(block: suspend () -> T): ApiResult<T> = try {
312	    ApiResult.Success(block())
313	} catch (e: Exception) {
314	    ApiResult.Error(e.toNetworkException())
315	}
316	
317	// Usage
318	val result: ApiResult<User> = apiCall { userApi.getUser("123") }
319	when (result) {
320	    is ApiResult.Success -> showUser(result.data)
321	    is ApiResult.Error -> showError(result.error)
322	}
