354	
355	```kotlin
356	// commonMain/kotlin/network/OfflineCapableApi.kt
357	class OfflineCapableApi<T : Any>(
358	    private val api: T,
359	    private val cache: DatabaseCache
360	) : OfflineCapableApi<T> by api {
361	
362	    suspend fun <R> withCache(
363	        key: String,
364	        ttl: Duration,
365	        block: suspend () -> R
366	    ): R = withContext(Dispatchers.IO) {
367	        // Try cache first
368	        cache.get<R>(key)?.let { cached ->
369	            if (cached.timestamp + ttl.toMillisMilliseconds() > Clock.System.now()) {
370	                return@withContext cached.data
371	            }
372	        }
373	
374	        // Fetch from network
375	        try {
376	            val result = block()
377	            cache.put(key, CachedData(result, Clock.System.now()))
378	            result
379	        } catch (e: NetworkException) {
380	            // Return stale cache if network fails
381	            cache.get<R>(key)?.data ?: throw e
382	        }
383	    }
384	}
